package com.mealmate.notification; import jakarta.persistence.*; import java.util.*; @Entity public class Notification{@Id @GeneratedValue private Long id;private UUID orderId;private String eventType;private String message;@Column(unique=true)private String eventId;protected Notification(){}Notification(UUID o,String t,String m,String e){orderId=o;eventType=t;message=m;eventId=e;}public UUID getOrderId(){return orderId;}public String getMessage(){return message;}}
